"use strict";if(oaData){const oaWrapper=document.querySelector('[data-container-id="oa-wrapper"]');const submitButtons=document.querySelectorAll(".oa-submit-widget button[type=submit]");window.oa={res:oaData.res,agendaUid:oaData.agendaUid,locale:oaData.locale,query:window.location.search,page:parseInt(oaData.page)||1,size:parseInt(oaData.size),observer:null,values:{},aggregations:{},manualSubmit:oaData.manualSubmit&&submitButtons.length>0,onLoad:async(values,aggregations,filtersRef,_form)=>{oa.setupObserver();oa.setupManualSubmit(_form);try{oa.values=values;oa.aggregations=aggregations;const result=await oa.getEvents({...values,size:0},aggregations);filtersRef.updateLocation(values);filtersRef.updateFiltersAndWidgets(values,result)}catch(e){console.log("onLoad error: ",e)}},onPendingChange:pending=>{if(oa.manualSubmit&&submitButtons.length>0){submitButtons.forEach(button=>{pending?button.removeAttribute("disabled"):button.setAttribute("disabled",true)})}},onFilterChange:async(values,aggregations,filtersRef,_form)=>{oa.values=values;oa.aggregations=aggregations;oa.page=1;oaWrapper.insertAdjacentHTML("afterbegin",oaData.overlayHtml);try{if(oaData.isSingle&&oaData.listUrl){if(values.context)delete values.context;const url=`${oaData.listUrl}?${Qs.stringify(values)}`;window.location.href=url}else{const result=await oa.getEvents(values,aggregations);if(result.success&&result.html){oa.updateHTML(oaWrapper,result.html);oa.setupObserver();const url=`${oaData.listUrl}`;history.pushState(null,document.title,url);filtersRef.updateLocation(values);filtersRef.updateFiltersAndWidgets(values,result)}else{console.log(result);if(result.data&&result.data.length>0){oa.updateHTML(oaWrapper,oaData.errorNotice)}}}}catch(e){console.log("onFilterChange error: ",e);oa.updateHTML(oaWrapper,oaData.errorNotice)}},setupObserver:()=>{const eventsWrapper=document.querySelector('[data-container-id="oa-events"],.oa-event-grid,.oa-event-list');if(eventsWrapper&&oaData.infiniteScroll&&!oaData.isSingle){if(oa.observer!==null){oa.observer.unobserve(oa.observed);oa.observer=null}oa.observed=eventsWrapper.querySelector(".oa-event:last-child");if(!oa.observed)return;oa.observer=new IntersectionObserver(oa.onIntersect,{});oa.observer.observe(oa.observed)}},setupManualSubmit:_form=>{if(oa.manualSubmit){const submitButtons=document.querySelectorAll(".oa-submit-widget button[type=submit]");if(submitButtons.length>0){submitButtons.forEach(button=>{button.setAttribute("disabled",true);button.addEventListener("click",async e=>{e.preventDefault();_form.submit()})})}}},onIntersect:(entries,observer)=>{entries.forEach(async entry=>{if(!entry.isIntersecting)return;const loaded=await oa.loadMore();if(loaded){oa.setupObserver()}else{oa.observer.unobserve(oa.observed)}})},loadMore:async()=>{try{oa.page+=1;const result=await oa.getEvents(oa.values,oa.aggregations,{isLoadingMore:true});if(result.success&&result.events?.length>0&&result.html!==""){const eventsWrapper=document.querySelector('[data-container-id="oa-events"],.oa-event-grid,.oa-event-list');eventsWrapper.insertAdjacentHTML("beforeend",result.html);return true}else{return false}}catch(e){console.log("loadMore error: ",e);return false}},getEvents:async(values,aggregations=[],additional_args=[])=>{const args={postId:oaData.postId,action:oaData.action,view:oaData.view,page:parseInt(window.oa.page),size:parseInt(window.oa.size),...additional_args};const url=`${oaData.ajaxUrl}?${Qs.stringify({...args,...values,aggregations:aggregations})}`;const result=await fetch(url).then(response=>response.json());return result},updateHTML:(element,html)=>{element.innerHTML=html}}}